import platform
import re
import socketserver
import threading
import time
from http.server import HTTPServer, BaseHTTPRequestHandler


def get_cpu_percent():
    """Get CPU usage percentage using /proc/stat on Linux or resource.getloadavg()."""
    system = platform.system()

    if system == "Linux":
        return _get_cpu_usage_linux()
    elif system == "Windows":
        return _get_cpu_usage_windows()
    elif system in ["Darwin", "MacOS"]:
        return _get_cpu_usage_macos()
    else:
        # Fallback to load average for other systems
        try:
            loadavg = os.getloadavg()
            cpu_count = os.cpu_count() or 1
            return round((loadavg[0] / cpu_count) * 100, 2)
        except (OSError, AttributeError):
            return 0.0


def get_memory_percent():
    """Get memory usage percentage."""
    try:
        system = platform.system()

        if system == "Linux":
            return _get_memory_usage_linux()
        elif system == "Windows":
            import subprocess
            result = subprocess.run(
                ["wmic", "os", "get", "TotalVisibleMemorySize,FreePhysicalMemory"],
                capture_output=True, text=True
            )
            lines = result.stdout.split("\n")
            for line in lines:
                if "TotalVisibleMemorySize" in line:
                    total = int(line.split(":")[1].strip())
                if "FreePhysicalMemory" in line:
                    free = int(line.split(":")[1].strip())
                    return round(((total - free) / total) * 100, 2)
            return 0.0

        # Unix-like systems (Unix, AIX, etc.)
        import resource
        rusage = resource.getrusage(resource.RUSAGE_SELF)
        memory_info = rusage.ru_maxrss  # In KB on Unix
        try:
            with open("/proc/meminfo") as f:
                mem_lines = f.readlines()
            total_mem = int(re.search(r"^MemTotal:\s+(\d+)", "\n".join(mem_lines)).group(1))
            return round((memory_info * 1024 / total_mem) * 100, 2)
        except Exception:
            # Fallback to resource usage if proc/meminfo not available
            try:
                mem_used_kb = memory_info - rusage.ru_maxrss
                return round(((rusage.ru_maxrss) / (memory_info)) * 100, 2)
            except:
                return 0.0

    except Exception:
        return 0.0


def _get_cpu_usage_linux():
    """Calculate CPU usage from /proc/stat."""
    def read_proc_stat():
        with open("/proc/stat") as f:
            line = f.readline().strip()
            parts = line.split()
            cpu_line = {parts[0]: int(x) for x in parts[1:]}
            return tuple(cpu_line.values())

    # First read
    cpu_times_1 = read_proc_stat()
    time.sleep(0.5)
    # Second read
    cpu_times_2 = read_proc_stat()

    n = len(cpu_times_1)
    total_diff = sum(cpu_times_2[i] - cpu_times_1[i] for i in range(n))
    idle_diff = cpu_times_2[n-1] - cpu_times_1[n-1]  # Last value is typically 'idle'

    return round(((total_diff - idle_diff) / total_diff * 100), 2) if total_diff > 0 else 0.0


def _get_memory_usage_linux():
    """Get memory usage from /proc/meminfo."""
    try:
        with open("/proc/meminfo") as f:
            lines = f.readlines()

        mem_total = int(re.search(r"^MemTotal:\s+(\d+)", "\n".join(lines)).group(1))
        mem_available = int(re.search(r"^MemAvailable:\s+(\d+)", "\n".join(lines)).group(1) or 0)

        used = mem_total - mem_available
        return round((used / mem_total) * 100, 2) if mem_total > 0 else 0.0
    except Exception:
        return 0.0


def _get_cpu_usage_windows():
    """Get CPU usage on Windows using performance counter."""
    try:
        import subprocess
        result = subprocess.run(
            ["wmic", "processor", "get", "LoadPercentage"],
            capture_output=True, text=True
        )
        # Parse output (e.g., "LoadPercentage\n42")
        for line in result.stdout.split("\n"):
            if "LoadPercentage" in line:
                return int(line.strip().split(":")[1])
        return 0.0
    except Exception:
        return 0.0


def _get_cpu_usage_macos():
    """Get CPU usage on macOS using psutil alternative or system stats."""
    try:
        import subprocess
        result = subprocess.run(
            ["sysctl", "-n", "machdep.cpu.logical_per_package"],
            capture_output=True, text=True
        )
        # Fallback approach - use load average if possible
        loadavg = os.getloadavg()
        cpu_count = os.cpu_count() or 1
        return round((loadavg[0] / cpu_count) * 100, 2)
    except Exception:
        return 0.0


class CPURequestHandler(BaseHTTPRequestHandler):
