        """Handle GET requests by sending JSON or HTML."""
        if self.path == "/api/status":
            # Send API endpoint for AJAX calls
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            data = {
                "cpu_percent": get_cpu_percent(),
                "memory_percent": get_memory_percent()
            }
            self.wfile.write(json.dumps(data).encode())
        elif self.path == "/status.html":
            # Send HTML page with embedded JavaScript for auto-updating
            html = self.generate_html_page()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(html.encode())
        else:
            # Serve default index page
            html = self.generate_html_page()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(html.encode())

